    { ariaLabel: "Mutig führen, Teams stärken, Performance steigern", href: "/1685", kind: "image", imgSrc: "/assets/cloned/images/da4fead7b314.jpg", label: "\n\t\t\t\t\t\t\t\t\t\t\t\t\tNew Leadership", label2: "\n\t\t\t\t\t\t\t\t\t\t\t\tMutig führen, Teams stärken, Performance steigern", description: "New Leadership steigert die Team Performance durch Mut und Empowerment. Starke Werte und eine positive Unternehmenskultur helfen, auch in unsicheren Zeiten erfolgreich zu führen. Jetzt die Zukunft der Führung gestalten." },
    { ariaLabel: "Persönliche Weiterentwicklung im 1:1 ", href: "/1685", imgSrc: "/assets/cloned/images/d3d53871a324.jpg", label: "\n\t\t\t\t\t\t\t\t\t\t\t\t\tBusiness Coaching", label2: "\n\t\t\t\t\t\t\t\t\t\t\t\tPersönliche Weiterentwicklung im 1:1 ", description: "Im Business Coaching arbeitest du mit erfahrenen Coaches an deinen persönlichen Entwicklungszielen und beruflichen Herausforderungen. Für mehr Klarheit, neue Perspektiven und Wirksamkeit im Arbeitsalltag." },
    { ariaLabel: "Turn potential into progress", href: "/1685", imgSrc: "/assets/cloned/images/634aefec9192.jpg", label: "\n\t\t\t\t\t\t\t\t\t\t\t\t\tDigital Suite", label2: "\n\t\t\t\t\t\t\t\t\t\t\t\tTurn potential into progress", description: "Digitales Lernen aus einer Hand: Die Digital Suite liefert dir mit ihrer großen Vielfalt die Lösung, die am Besten zu deinen Bedarfen und Zielen passt – vom Content-Baustein bis zur Lernplattform." },
    { ariaLabel: "Eine Plattform. Alle Weiterbildungen.", href: "https://www.semigator.de/enterprise/", imgSrc: "/assets/cloned/images/88cdedcf4aa5.jpg", label: "\n\t\t\t\t\t\t\t\t\t\t\t\t\tSemigator Enterprise", label2: "\n\t\t\t\t\t\t\t\t\t\t\t\tEine Plattform. Alle Weiterbildungen.", description: "Mit der Semigator Enterprise Plattform organisierst du externe Trainings und Coachings mühelos. Alles aus einer Hand, integriert in deine HR- und Einkaufssysteme." },
    { ariaLabel: "Persönliche & Soziale Kompetenzen", href: "/blog/berufe", kind: "image", imgSrc: "/assets/cloned/images/634375581917.png", label: "\n\t\t\t\t\t\t\t\t\t\t\t\t\tSeminare & Trainings", label2: "\n\t\t\t\t\t\t\t\t\t\t\t\tPersönliche & Soziale Kompetenzen", description: "Zeig Wirkung, wo es wirklich zählt. Deine Soft Skills sind entscheidend und lassen sich trainieren. Mit fundiertem Know-how und direktem Praxistransfer." }
